function TaskCount({ tasks }: { tasks: { done: boolean }[] }) {
  const open = tasks.filter(task => !task.done).length;
  return <p>{open} open tasks</p>;
}

function TaskItem({ title, done }: { title: string; done: boolean }) {
  return <li aria-label={done ? "completed" : "open"}>{title}</li>;
}

